CREATE TYPE "KnowledgeImportStatus" AS ENUM ('UPLOADED','PROCESSING','REVIEW','READY','APPLIED','FAILED');
CREATE TYPE "KnowledgeImportItemStatus" AS ENUM ('CREATE','UPDATE','SKIP','NEEDS_REVIEW','CONFLICT','APPROVED','REJECTED','APPLIED','FAILED');
CREATE TABLE "KnowledgeImportSession" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "workspaceId" UUID NOT NULL, "createdById" UUID, "status" "KnowledgeImportStatus" NOT NULL DEFAULT 'UPLOADED', "templateVersion" TEXT, "idempotencyKey" TEXT, "errorSummary" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "KnowledgeImportSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KnowledgeImportFile" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "workspaceId" UUID NOT NULL, "sessionId" UUID NOT NULL, "fileName" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "storageKey" TEXT, "sha256" TEXT NOT NULL, "byteCount" INTEGER NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "KnowledgeImportFile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KnowledgeImportItem" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "workspaceId" UUID NOT NULL, "sessionId" UUID NOT NULL, "fileId" UUID, "entityType" TEXT NOT NULL, "destination" TEXT NOT NULL, "status" "KnowledgeImportItemStatus" NOT NULL DEFAULT 'NEEDS_REVIEW', "sourceLocator" TEXT, "sourceExcerpt" TEXT, "payload" JSONB NOT NULL, "existingValue" JSONB, "proposedValue" JSONB, "confidence" DOUBLE PRECISION, "conflictReason" TEXT, "appliedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "KnowledgeImportItem_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "KnowledgeImportSession_workspaceId_idempotencyKey_key" ON "KnowledgeImportSession"("workspaceId","idempotencyKey");
CREATE UNIQUE INDEX "KnowledgeImportFile_workspaceId_sha256_key" ON "KnowledgeImportFile"("workspaceId","sha256");
CREATE INDEX "KnowledgeImportSession_workspaceId_createdAt_idx" ON "KnowledgeImportSession"("workspaceId","createdAt");
CREATE INDEX "KnowledgeImportFile_workspaceId_sessionId_idx" ON "KnowledgeImportFile"("workspaceId","sessionId");
CREATE INDEX "KnowledgeImportItem_workspaceId_sessionId_status_idx" ON "KnowledgeImportItem"("workspaceId","sessionId","status");
ALTER TABLE "KnowledgeImportSession" ADD CONSTRAINT "KnowledgeImportSession_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "KnowledgeImportFile" ADD CONSTRAINT "KnowledgeImportFile_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "KnowledgeImportFile_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "KnowledgeImportSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "KnowledgeImportItem" ADD CONSTRAINT "KnowledgeImportItem_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "KnowledgeImportItem_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "KnowledgeImportSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
